  // ==== Cross-section combo programmes ====
  // A combo programme chains blocks from any of the four sections behind
  // one code or one locally-saved plan - each block just says which
  // section's engine should run it (`domain`) plus that engine's own
  // settings. The dispatcher below reuses every section's existing start/
  // finish functions rather than a parallel implementation.
  function comboBlockLabel(block) {
    if (block.domain === "wimhof") return WIMHOF_INFO.name;
    if (block.domain === "breath") return BREATH_PATTERNS[block.pattern].name;
    if (block.domain === "movement") return "Reaktionstraining · Ganzkörper-Reaktion";
    if (block.domain === "workout") return workoutBlockLabel(block);
    if (block.domain === "visual") {
      const t = EXERCISES[block.exercise] ? EXERCISES[block.exercise].title : block.exercise;
      // Farbfelder: name the mode like the NAT blocks do (9 very different modes).
      return block.ff && FF_MODE_LABELS[block.ff.ffMode] ? `${t} · ${FF_MODE_LABELS[block.ff.ffMode]}` : t;
    }
    if (block.domain === "nat") return `Positionen merken · ${REMEMBER_MODES[block.mode] ? REMEMBER_MODES[block.mode].title : block.mode}`;
    if (block.domain === "blitz") return "Blitz-Raster";
    if (block.domain === "flash") return `Flash-Speicher-Test · ${flashModeTitle(block.mode)}`;
    if (block.domain === "mot") return `Objektverfolgung (MOT) · ${motModeTitle(block.mode)}`;
    if (block.domain === "balance") return `Gleichgewicht · ${BALANCE_MODES[balanceBlockPrefs(block).mode].name}`;
    if (block.domain === "cardio") return `Ausdauertraining · ${countLabel(block.items.length, "Aktivität", "Aktivitäten")}`;
    if (block.domain === "free") return block.free.title;
    if (block.domain === "optodrum") return `Optodrum · ${OPTO_PATTERNS[optoBlockPrefs(block).pattern].name}`;
    return block.domain;
  }
  function comboBlockMeta(block) {
    if (block.domain === "wimhof") return `${block.rounds ?? WIMHOF_DEFAULTS.rounds} Runden` + (whRoundRestOf(block) ? ` · ${whRoundRestOf(block)} s Pause` : "");
    if (block.domain === "breath") return (block.noLimit ? "ohne Zeitlimit" : fmtMinutes((block.durationMin ?? 5) * 60)) + (block.listen ? " · Hörmodus" : "");
    if (block.domain === "movement") return fmtMinutes((block.durationMin ?? 2) * 60);
    if (block.domain === "workout") return workoutBlockMeta(block);
    if (block.domain === "visual") return fmtMinutes((block.duration ?? 60));
    if (block.domain === "nat") return fmtMinutes((block.duration ?? 60));
    if (block.domain === "blitz") return fmtMinutes((block.duration ?? 60));
    if (block.domain === "flash") return fmtMinutes((block.duration ?? 60));
    if (block.domain === "mot") return fmtMinutes((block.duration ?? 60));
    if (block.domain === "balance") return balanceMeta(balanceBlockPrefs(block));
    if (block.domain === "cardio") return fmtMinutes(cardioItemsSeconds(block.items));
    if (block.domain === "free") return freeBlockMeta(block.free);
    if (block.domain === "optodrum") { const p = optoBlockPrefs(block); return `${optoTimeLabel(p)} · ${optoDirName(p)} · Stufe ${p.speed}`; }
    return "";
  }
  function comboBlockSeconds(block) {
    if (block.domain === "wimhof") { const r = block.rounds ?? WIMHOF_DEFAULTS.rounds, n = block.breaths ?? WIMHOF_DEFAULTS.breaths; return r * (n * (block.breathPaceS ?? WIMHOF_DEFAULTS.breathPaceS) + 30 + (block.recoveryHoldS ?? WIMHOF_DEFAULTS.recoveryHoldS)) + Math.max(0, r - 1) * whRoundRestOf(block); }
    if (block.domain === "breath") return block.noLimit ? 0 : (block.durationMin ?? 5) * 60;
    if (block.domain === "movement") return (block.durationMin ?? 2) * 60;
    if (block.domain === "workout") return workoutBlockSeconds(block);
    if (block.domain === "visual") return block.duration ?? 60;
    if (block.domain === "nat") return block.duration ?? 60;
    if (block.domain === "blitz") return block.duration ?? 60;
    if (block.domain === "flash") return block.duration ?? 60;
    if (block.domain === "mot") return block.duration ?? 60;
    if (block.domain === "balance") return balanceTotalSeconds(balanceBlockPrefs(block));
    if (block.domain === "cardio") return cardioItemsSeconds(block.items);
    if (block.domain === "free") return freeBlockSeconds(block.free);
    if (block.domain === "optodrum") { const p = optoBlockPrefs(block); return p.noLimit ? 0 : p.durationS; }
    return 0;
  }
  // Curated quick-add presets the combo builder offers per section - not the
  // full settings depth of each section's own screen, but enough to build a
  // useful cross-section session without reimplementing every settings UI.
  // Empty now - Remember (the last domain still using this) moved to
