  els.trainingHub = $("trainingHub"); els.moreScreen = $("moreScreen");
  els.freeHome = $("freeHome"); els.freeReady = $("freeReady"); els.freeEdit = $("freeEdit"); els.freePlayer = $("freePlayer");
  els.activationHome = $("activationHome"); els.optoReady = $("optoReady"); els.optoPlayer = $("optoPlayer");
  const SCREENS = ["todayHome", "trainingHub", "moreScreen", "planScreen", "myPlanScreen", "progressScreen", "home", "breathHome", "movementHome", "workoutHome", "cardioHome", "natHome", "testHome", "freeHome", "freeReady", "freeEdit", "activationHome", "optoReady", "bundleOverview", "programIntro", "ready", "breathReady", "breathBundleOverview", "breathProgramIntro", "wimhofReady", "movementReady", "movementBundleOverview", "movementProgramIntro", "workoutBundleOverview", "workoutProgramIntro", "workoutTabataReady", "workoutRepsReady", "cardioReady", "cardioBundleOverview", "cardioProgramIntro", "comboScreen", "comboBundleOverview", "rememberReady", "rememberTrainingReady", "blitzReady", "flashReady", "flashTrainingReady", "motReady", "motTrainingReady", "balanceReady", "gngReady", "testNbackReady", "trailReady", "flankerReady", "ufovReady", "posnerReady", "rotationReady", "merkReady", "simonReady", "searchReady", "abReady", "antizipReady", "hickReady", "corsiReady", "reaktReady", "tsReady", "antiReady", "stroopReady", "subitizeReady", "alarmReady", "vorlaufReady", "stopReady", "dsstReady", "wcstReady", "navonReady", "iconicReady", "pvtReady", "bisectReady", "kippbildReady", "eyecountReady"];
  function showScreen(name) {
    SCREENS.forEach((s) => { els[s].hidden = s !== name; });
    if (name === "home" || name === "breathHome" || name === "movementHome" || name === "workoutHome") renderHistory();
    if (name === "todayHome") renderToday();
    if (name === "progressScreen") renderProgressScreen();
    if (name === "freeHome") renderFreeHome();
    if (name === "activationHome") renderActivationHome();
    if (name !== "activationHome") $("activationProgramError").hidden = true;
    if (name !== "freeHome") $("freeProgramError").hidden = true;
    if (name !== "todayHome" && els.todayCodeError) els.todayCodeError.hidden = true;
    if (name !== "home") els.programError.hidden = true;
    if (name !== "breathHome") els.breathProgramError.hidden = true;
    if (name !== "movementHome") els.movementProgramError.hidden = true;
    if (name !== "workoutHome") els.workoutProgramError.hidden = true;
    if (name !== "cardioHome") els.cardioProgramError.hidden = true;
    if (name !== "natHome") els.natProgramError.hidden = true;
    if (name !== "trainingHub") $("moreCodeError").hidden = true;
    syncNatModeRows(name);
    if (NAT_SAVED) NAT_SAVED(name);
    window.scrollTo(0, 0);
  }

  // ---- Section switcher (Visual Training / Atemtraining) ----
  let freeAreaActive = false; // "Freie Bausteine" has no tab of its own (reached via Training / Heute)
  let activationAreaActive = false; // Aktivierung: no tab either (2026-10-08)
  function activateSectionTab(sec) {
    freeAreaActive = sec === "free";
    activationAreaActive = sec === "activation";
    document.querySelectorAll(".section-tab").forEach((b) => {
      const on = b.dataset.section === sec;
      b.classList.toggle("active", on);
      b.setAttribute("aria-selected", on ? "true" : "false");
    });
  }
  document.querySelectorAll(".section-tab").forEach((btn) => {
    btn.addEventListener("click", () => {
      const sec = btn.dataset.section;
      activateSectionTab(sec);
      showScreen(sec === "today" ? "todayHome" : sec === "breath" ? "breathHome" : sec === "movement" ? "movementHome" : sec === "workout" ? "workoutHome" : sec === "cardio" ? "cardioHome" : sec === "nat" ? "natHome" : sec === "test" ? "testHome" : "home");
    });
  });

  // ---- NAT sub-navigation (second-level tabs within the NAT section) ----
  document.querySelectorAll(".sub-tab").forEach((btn) => {
    btn.addEventListener("click", () => {
      const sub = btn.dataset.natSub;
      document.querySelectorAll(".sub-tab").forEach((b) => {
        const on = b.dataset.natSub === sub;
        setActive(b, on);
        b.setAttribute("aria-selected", on ? "true" : "false");
      });
      els.natPeripherPanel.hidden = sub !== "peripher";
      els.natRememberPanel.hidden = sub !== "remember";
      els.natBlitzPanel.hidden = sub !== "blitz";
      els.natFlashPanel.hidden = sub !== "flash";
      els.natMotPanel.hidden = sub !== "mot";
      els.natBalancePanel.hidden = sub !== "balance";
      if (sub === "remember") renderRememberBests();
      if (sub === "blitz") renderBlitzBest();
      if (sub === "flash") renderFlashBests();
      if (sub === "mot") renderMotBests();
    });
  });
  document.querySelectorAll("[data-open-combo]").forEach((btn) => btn.addEventListener("click", () => openComboScreen()));

  // ---- NAT wie alle Bereiche (Fabian, 2026-10-05 "Alle Bereiche gleich
  // aufbauen"): no second tab row; the five exercises are tiles under
  // "Einzelne Übungen" like Atemmuster/Visual Training, and the old variant
  // cards (fest/bewegt, konstant/steigend, Tempo/Anzahl, Trainingsmodus)
  // become a "Modus" choice on the exercise's own ready screen. The old
  // cards and sub-tabs stay in the DOM (hidden) and are what the mode
  // buttons click, so every opener, Kombi capture and Heute path is
  // unchanged. Automated browsers keep the old layout unless
  // fwmc-test-natmodes is set (many tests click the NAT sub-tabs).
  const NAT_MODES = {
    remember: { title: "Positionen merken", modes: [
      { key: "fixed", label: "Feste Positionen", sub: "Plätze bleiben", card: "rememberOpenFixed", screen: "rememberReady" },
      { key: "shuffle", label: "Bewegte Positionen", sub: "neu gemischt", card: "rememberOpenShuffle", screen: "rememberReady" },
      { key: "training", label: "Trainingsmodus", sub: "gezielt üben", card: "rememberOpenTraining", screen: "rememberTrainingReady" }] },
    flash: { title: "Flash-Speicher-Test", modes: [
      { key: "constant", label: "Konstant", sub: "gleich viele, schneller", card: "flashOpenConstant", screen: "flashReady" },
      { key: "climb", label: "Steigend", sub: "+1 nach Erfolg", card: "flashOpenClimb", screen: "flashReady" },
      { key: "climbRepeat", label: "Mit Wiederholung", sub: "+1 nach 2–3 Runden", card: "flashOpenClimbRepeat", screen: "flashReady" },
      { key: "training", label: "Trainingsmodus", sub: "gezielt üben", card: "flashOpenTraining", screen: "flashTrainingReady" }] },
    mot: { title: "Objektverfolgung (MOT)", modes: [
      { key: "speed", label: "Tempo steigt", sub: "immer schneller", card: "motOpenSpeed", screen: "motReady" },
      { key: "count", label: "Anzahl steigt", sub: "immer mehr Objekte", card: "motOpenCount", screen: "motReady" },
      { key: "both", label: "Beides steigt", sub: "Tempo und Anzahl", card: "motOpenBoth", screen: "motReady" },
      { key: "training", label: "Trainingsmodus", sub: "gezielt üben", card: "motOpenTraining", screen: "motTrainingReady" }] },
  };
  const NAT_MODE_KEY = "fwmc-nat-mode-v1";
  // Set further down (NAT presets); `var` so showScreen() can test it before.
  var NAT_SAVED = null;
  const natModesOn = !(navigator.webdriver && !readJSON("fwmc-test-natmodes", false));
  let natModeNav = null; // { ex, mode } while the client came from the NAT tiles
  const natModeScreens = new Set();
  Object.values(NAT_MODES).forEach((x) => x.modes.forEach((m) => natModeScreens.add(m.screen)));
  // One "Modus" row per ready screen, right under its description.
  natModeScreens.forEach((sid) => {
    const scr = document.getElementById(sid);
    const sub = scr && scr.querySelector(":scope > .page-sub");
    if (!sub) return;
    const ex = Object.keys(NAT_MODES).find((k) => NAT_MODES[k].modes.some((m) => m.screen === sid));
    const box = document.createElement("div");
    box.className = "group nat-mode-group";
    box.hidden = true;
    box.dataset.natEx = ex;
    box.innerHTML = `<div class="group-label">Modus</div><div class="choice-row${NAT_MODES[ex].modes.length === 3 ? "" : " two"}" role="group" aria-label="Modus">${NAT_MODES[ex].modes.map((m) => `<button type="button" class="choice" data-nat-mode="${m.key}">${esc(m.label)}<small>${esc(m.sub)}</small></button>`).join("")}</div>`;
    sub.after(box);
    const h1 = scr.querySelector(":scope > h1.page-title");
    if (h1) h1.dataset.natOrigTitle = h1.textContent;
    box.addEventListener("click", (e) => { const b = e.target.closest("[data-nat-mode]"); if (b) openNatMode(ex, b.dataset.natMode); });
  });
  function openNatMode(ex, modeKey) {
    const def = NAT_MODES[ex];
    const m = def.modes.find((x) => x.key === modeKey) || def.modes[0];
    const saved = readJSON(NAT_MODE_KEY, {});
    saved[ex] = m.key;
    writeJSON(NAT_MODE_KEY, saved);
    natModeNav = { ex, mode: m.key };
    els[m.card].click();
  }
  function openNatExercise(ex) {
    if (NAT_MODES[ex]) { openNatMode(ex, readJSON(NAT_MODE_KEY, {})[ex]); return; }
    natModeNav = null;
    if (ex === "peripher") els.periphOpenBtn.click();
    else if (ex === "blitz") els.blitzOpenBtn.click();
    else if (ex === "balance") els.balanceOpenBtn.click();
  }
  function syncNatModeRows(name) {
    if (natModeNav && (!natModeScreens.has(name) || !NAT_MODES[natModeNav.ex].modes.some((m) => m.screen === name))) natModeNav = null;
    document.querySelectorAll(".nat-mode-group").forEach((box) => {
      const scr = box.closest(".screen");
      const on = !!(natModesOn && natModeNav && scr && scr.id === name && box.dataset.natEx === natModeNav.ex);
      box.hidden = !on;
      const h1 = scr && scr.querySelector(":scope > h1.page-title");
      if (scr && scr.id === name && h1) h1.textContent = on ? NAT_MODES[natModeNav.ex].title : (h1.id ? h1.textContent : h1.dataset.natOrigTitle);
      if (on) box.querySelectorAll("[data-nat-mode]").forEach((b) => {
        const act = b.dataset.natMode === natModeNav.mode;
        b.classList.toggle("active", act);
        b.setAttribute("aria-pressed", act ? "true" : "false");
      });
    });
  }
  if (natModesOn) {
    document.body.classList.add("nat-modes");
    els.natHome.querySelector("#natExercises").hidden = false;
    els.natHome.querySelectorAll("[data-nat-ex]").forEach((b) => b.addEventListener("click", () => openNatExercise(b.dataset.natEx)));
  }

  // ---- Storage (all local to this device, wrapped for private mode) ----
  function readJSON(key, fallback) {
    try { const raw = localStorage.getItem(key); return raw ? JSON.parse(raw) : fallback; } catch (e) { return fallback; }
  }
  function writeJSON(key, value) {
    try { localStorage.setItem(key, JSON.stringify(value)); }
    catch (e) { if (e && (e.name === "QuotaExceededError" || e.code === 22 || e.code === 1014)) showStorageFullWarning(); }
  }
  // A full storage used to fail silently (settings and history simply
  // stopped saving). Tell the client once per page load what happened.
  let storageWarningShown = false;
  function showStorageFullWarning() {
    if (storageWarningShown || !document.body) return;
    storageWarningShown = true;
    const box = document.createElement("div");
    box.className = "storage-warning";
    box.id = "storageWarning";
    box.setAttribute("role", "alert");
    const text = document.createElement("p");
    text.textContent = "Der Speicher dieses Browsers ist voll. Neue Einstellungen und Verlaufseinträge werden gerade nicht gespeichert. Tipp: Motivationsbilder im Bereich Ausdauertraining entfernen und unter Grundeinstellungen eine Datensicherung exportieren.";
    const btn = document.createElement("button");
    btn.type = "button";
    btn.textContent = "Verstanden";
    btn.addEventListener("click", () => box.remove());
    box.append(text, btn);
    document.body.appendChild(box);
  }

  // ---- Training history ----
  const HISTORY_KEY = "fwmc-history-v1";
  // Entries saved before the renaming of 2026-10-02 still carry the old
  // exercise names; show the current ones everywhere (history, "Weitermachen").
  const HISTORY_RENAMES = [[/^Remember\b/, "Positionen merken"], [/MOT-Fähigkeit/g, "Objektverfolgung (MOT)"], [/Flash Speicher Test/g, "Flash-Speicher-Test"]];
  function loadHistory() {
    const h = readJSON(HISTORY_KEY, []);
    if (!Array.isArray(h)) return [];
    h.forEach((e) => { if (e && typeof e.title === "string") HISTORY_RENAMES.forEach(([re, to]) => { e.title = e.title.replace(re, to); }); });
    return h;
  }
  // A done panel shows either "geschafft" (check mark + its own heading) or
  // "beendet" when the client skipped past the end (Fabian, 2026-10-02:
  // skipping to the end counts as aborted, not completed).
  function setDonePanelAborted(panel, aborted, abortedTitle) {
    const check = panel.querySelector(".done-check");
    const h = panel.querySelector("h2");
    if (h && h.dataset.doneTitle == null) h.dataset.doneTitle = h.textContent;
    if (check) check.hidden = !!aborted;
    if (h) h.textContent = aborted ? abortedTitle : h.dataset.doneTitle;
  }
  // True while the « ↻ » bar silently stops a run to restart or jump - that
  // stop must not leave a history entry (see updateStepNav).
  let stepNavSilent = false;
  function addHistory(entry) {
    if (stepNavSilent) return null;
    const list = loadHistory();
    const item = { id: String(Date.now()), ts: new Date().toISOString(), rating: null, ...entry };
    list.unshift(item);
    writeJSON(HISTORY_KEY, list.slice(0, 200));
    recordProgress(item);
    reminderPlanChanged(); // a finished training ticks its plan entry: drop its reminder
    return item.id;
  }
  function rateHistory(id, rating) {
    const list = loadHistory();
    const item = list.find((e) => e.id === id);
    if (item) { item.rating = rating; writeJSON(HISTORY_KEY, list); }
  }
  // ==== Mein Fortschritt (Fabian, 2026-10-03: "umsetzen") ====
  // Weekly goal, a week streak, milestones and an overview across all areas.
  // The history keeps only the last 200 runs, so lifetime numbers live in
  // their own store, filled by addHistory() (recordProgress) and seeded once
  // from the existing history. Aborted runs never count.
  const PROGRESS_KEY = "fwmc-progress-v1";
  const PROGRESS_MILESTONES = [1, 5, 10, 25, 50, 100, 150, 200, 300, 500, 750, 1000];
  function loadProgress() {
    const raw = readJSON(PROGRESS_KEY, null);
    const p = raw && typeof raw === "object" ? raw : {};
    const goal = Math.round(Number(p.weekGoal));
    const out = {
      weekGoal: goal >= 1 && goal <= 14 ? goal : 3,
      days: p.days && typeof p.days === "object" ? p.days : {},
      seeded: !!p.seeded,
    };
    if (!out.seeded) {
      loadHistory().forEach((e) => { if (!e.aborted) progressAdd(out, e); });
      out.seeded = true;
      writeJSON(PROGRESS_KEY, out);
    }
    return out;
  }
  function progressDay(ts) {
    const d = new Date(ts);
    return `${d.getFullYear()}-${String(d.getMonth() + 1).padStart(2, "0")}-${String(d.getDate()).padStart(2, "0")}`;
  }
  function progressAdd(p, e) {
    const key = progressDay(e.ts || Date.now());
    const day = p.days[key] || (p.days[key] = { n: 0, s: 0, a: {} });
    const area = historyAreaOf(e);
    day.n += 1;
    day.s += Math.max(0, Math.round(Number(e.seconds) || 0));
    day.a[area] = (day.a[area] || 0) + 1;
  }
  function recordProgress(e) {
    if (!e || e.aborted) return;
    const p = loadProgress();
    progressAdd(p, e);
    writeJSON(PROGRESS_KEY, p);
  }
  function progressMonday(d) {
    const x = new Date(d.getFullYear(), d.getMonth(), d.getDate());
    x.setDate(x.getDate() - ((x.getDay() + 6) % 7));
    return x;
  }
  function progressWeek(p, monday) {
    let n = 0, s = 0;
    const a = {};
    for (let i = 0; i < 7; i++) {
      const d = new Date(monday); d.setDate(d.getDate() + i);
      const day = p.days[progressDay(d)];
      if (!day) continue;
      n += day.n; s += day.s;
      Object.entries(day.a || {}).forEach(([k, v]) => { a[k] = (a[k] || 0) + v; });
    }
    return { n, s, a };
  }
  // Wochenziel folgt dem Plan (kp2, Fabian 06.10.): with a plan for that
  // week the goal is what was planned (phases taken out of the rating and
  // pause days don't count), reached = the planned trainings were done;
  // more is shown as "zusätzlich" but never rewarded. Without a plan the
  // client's own number counts as before. A pause week neither reaches nor
  // breaks the streak.
  function weekGoalInfo(p, monday, hist) {
    const w = progressWeek(p, monday);
    const mon = dStr(monday);
    let st = null;
    try { if (planHasEntries() && dAdd(mon, 6) >= plan.startDate) st = weekStats(mon, hist); } catch (e) { st = null; }
    if (st && st.pauseWeek) return { ...w, goal: 0, planDone: 0, extra: w.n, fromPlan: true, pause: true, reached: false };
    if (st && st.scored > 0) {
      const planDone = Math.min(st.scoredDone, st.scored);
      return { ...w, goal: st.scored, planDone, extra: Math.max(0, w.n - planDone), fromPlan: true, reached: planDone >= st.scored };
    }
    if (st && st.planned > 0 && st.scored === 0) return { ...w, goal: 0, planDone: 0, extra: w.n, fromPlan: true, noScore: true, reached: false };
    return { ...w, goal: p.weekGoal, planDone: Math.min(w.n, p.weekGoal), extra: Math.max(0, w.n - p.weekGoal), fromPlan: false, reached: w.n >= p.weekGoal };
  }
  function progressSummary(p, now) {
    const thisMon = progressMonday(now || new Date());
    const weekAt = (back) => { const m = new Date(thisMon); m.setDate(m.getDate() - back * 7); return m; };
    const hist = loadHistory();
    const cur = weekGoalInfo(p, thisMon, hist);
    // Streak: weeks in a row with the goal reached. The running week only
    // counts once it is reached, so an unfinished week never breaks it;
    // pause weeks and weeks out of the rating are skipped.
    const neutral = (g) => g.pause || g.noScore;
    let streak = cur.reached ? 1 : 0;
    for (let back = 1; back < 520; back++) { const g = weekGoalInfo(p, weekAt(back), hist); if (neutral(g)) continue; if (g.reached) streak++; else break; }
    const days = Object.keys(p.days).sort();
    let best = 0;
    if (days.length) {
      let run = 0;
      const first = progressMonday(new Date(days[0] + "T12:00:00"));
      for (let m = new Date(first); m <= thisMon; m.setDate(m.getDate() + 7)) {
        const g = weekGoalInfo(p, m, hist);
        if (neutral(g)) continue;
        if (g.reached) { run++; best = Math.max(best, run); } else run = 0;
      }
    }
    let total = 0, totalS = 0;
    Object.values(p.days).forEach((d) => { total += d.n; totalS += d.s; });
    const weeks = [];
    for (let back = 7; back >= 0; back--) { const m = weekAt(back); weeks.push({ monday: m, ...weekGoalInfo(p, m, hist) }); }
    const areas = {};
    let areaS = 0;
    for (let back = 0; back < 4; back++) {
      const w = progressWeek(p, weekAt(back));
      Object.entries(w.a).forEach(([k, v]) => { areas[k] = (areas[k] || 0) + v; });
      areaS += w.s;
    }
    const next = PROGRESS_MILESTONES.find((m) => m > total) || null;
    return { cur, streak, best: Math.max(best, streak), total, totalS, weeks, areas, areaS, next };
  }
  const PROGRESS_AREA_LABEL = { combo: ["Kombi-Programm", "#007094"], test: ["Test-Bereich", "#b45309"] };
  function progressAreaInfo(k) {
    const a = AREA_BY_KEY[k];
    return a ? [a.label, a.color] : (PROGRESS_AREA_LABEL[k] || [k, "#6b7c85"]);
  }
  function progressStreakText(n) { return n === 1 ? "1 Woche" : `${n} Wochen`; }
  function curGoalText(c) {
    if (c.pause) return ["Pause", "Diese Woche zählt nicht"];
    if (c.noScore) return [`${c.n}`, "Diese Woche ohne Wertung"];
    return [`${c.planDone} von ${c.goal}${c.reached ? " ✓" : ""}`, c.reached ? "Wochenziel erreicht" : c.fromPlan ? "Wochenziel laut Plan" : "Wochenziel"];
  }
  function renderTodayProgressCard() {
    const p = loadProgress();
    const s = progressSummary(p);
    const c = s.cur;
    const [big, small] = curGoalText(c);
    const pct = c.goal ? Math.min(100, Math.round((c.planDone / c.goal) * 100)) : 0;
    els.todayProgressCard.innerHTML = `
      <div class="progress-card-row">
        <div><strong>${big}</strong><span>${small}${c.extra && c.goal ? ` · ${c.extra} zusätzlich` : ""}</span></div>
        <div><strong>${progressStreakText(s.streak)}</strong><span>Serie</span></div>
        <div><strong>${s.total}</strong><span>Trainings gesamt</span></div>
      </div>
      <div class="progress-bar" role="progressbar" aria-valuemin="0" aria-valuemax="${c.goal}" aria-valuenow="${Math.min(c.planDone, c.goal)}"><span style="width:${pct}%"></span></div>`;
  }
  function renderProgressScreen() {
    const p = loadProgress();
    const s = progressSummary(p);
    els.progressGoalValue.textContent = p.weekGoal === 1 ? "1 Training pro Woche" : `${p.weekGoal} Trainings pro Woche`;
    els.progressGoalMinus.disabled = p.weekGoal <= 1;
    els.progressGoalPlus.disabled = p.weekGoal >= 14;
    const c = s.cur;
    const goalNote = $("progressGoalPlanNote");
    if (goalNote) { goalNote.hidden = !c.fromPlan; goalNote.textContent = c.fromPlan ? "Solange ein Wochenplan läuft, richtet sich dein Wochenziel nach dem Plan. Diese Zahl gilt für Wochen ohne Plan." : ""; }
    const left = Math.max(0, c.goal - c.planDone);
    const pct = c.goal ? Math.min(100, Math.round((c.planDone / c.goal) * 100)) : 0;
    els.progressWeekBar.innerHTML = `<span style="width:${pct}%"></span>`;
    const extraTxt = c.extra && c.goal ? ` Dazu ${c.extra} zusätzlich.` : "";
    els.progressWeekText.textContent = c.pause ? "Diese Woche ist Pause. Deine Serie bleibt erhalten."
      : c.noScore ? `Diese Woche ist ohne Wertung. ${c.n} ${c.n === 1 ? "Training" : "Trainings"} bisher.`
      : left
      ? `Diese Woche ${c.planDone} von ${c.goal}${c.fromPlan ? " geplanten" : ""}. Noch ${left} bis zum Ziel.${extraTxt}`
      : `Diese Woche ${c.planDone} von ${c.goal}${c.fromPlan ? " geplanten" : ""}. Ziel erreicht, stark!${extraTxt}`;
    // No training yet (Fabian 2026-10-06): one friendly start card instead of
    // zeros and empty bars; the week goal stays adjustable above it.
    const empty = !s.total;
    els.progressEmpty.hidden = !empty;
    [els.progressStats, els.progressWeeks.closest(".group"), els.progressAreas.closest(".group"), els.progressMilestones.closest(".group")].forEach((el) => { if (el) el.hidden = empty; });
    els.progressStats.innerHTML =
      `<div class="stat"><strong>${progressStreakText(s.streak)}</strong><span>Serie (Wochenziel in Folge erreicht)</span></div>` +
      `<div class="stat"><strong>${progressStreakText(s.best)}</strong><span>Längste Serie</span></div>` +
      `<div class="stat"><strong>${s.total}</strong><span>Trainings gesamt</span></div>` +
      `<div class="stat"><strong>${s.totalS ? fmtMinutes(s.totalS) : "–"}</strong><span>Trainingszeit gesamt</span></div>`;
    // Split bars (kp2, Fabian 06.10.): below strong = planned and done,
    // above lighter and narrower = extra; each week its own goal tick.
    const maxN = Math.max(...s.weeks.map((w) => Math.max(w.goal * 1.25, w.planDone + w.extra)), 1);
    els.progressWeeks.innerHTML = s.weeks.map((w, i) => {
      const hp = Math.round((w.planDone / maxN) * 100), he = Math.round((w.extra / maxN) * 100);
      const label = i === s.weeks.length - 1 ? "diese" : `${String(w.monday.getDate()).padStart(2, "0")}.${String(w.monday.getMonth() + 1).padStart(2, "0")}.`;
      const title = w.pause ? "Pause" : `${w.planDone} von ${w.goal}${w.extra ? `, ${w.extra} zusätzlich` : ""}`;
      return `<div class="progress-week${w.reached ? " reached" : ""}${w.pause ? " pause" : ""}" title="${title}">
        <span class="progress-week-n">${w.pause ? "–" : w.planDone + w.extra}</span>
        <span class="progress-week-bar">${w.goal ? `<i class="progress-week-goal" style="bottom:${Math.round((w.goal / maxN) * 100)}%"></i>` : ""}<span class="pw-extra" style="height:${he}%;bottom:${hp}%"></span><span style="height:${hp}%"></span></span>
        <span class="progress-week-label">${label}</span></div>`;
    }).join("");
    els.progressWeeks.style.setProperty("--goal-pos", "-10%");
    const areaRows = Object.entries(s.areas).sort((a, b) => b[1] - a[1]);
    const maxA = Math.max(1, ...areaRows.map((r) => r[1]));
    els.progressAreas.innerHTML = areaRows.length
      ? areaRows.map(([k, n]) => {
          const [label, color] = progressAreaInfo(k);
          return `<div class="progress-area"><span class="progress-area-name">${esc(label)}</span>
            <span class="progress-area-bar"><span style="width:${Math.round((n / maxA) * 100)}%;background:${color}"></span></span>
            <span class="progress-area-n">${n}</span></div>`;
        }).join("")
      : `<p class="group-help">In den letzten 4 Wochen noch kein Training. Leg einfach los, dann siehst du hier, wie sich dein Training auf die Bereiche verteilt.</p>`;
    els.progressAreasNote.textContent = areaRows.length ? `Zusammen ${s.areaS ? fmtMinutes(s.areaS) : "unter einer Minute"} in den letzten 4 Wochen.` : "";
    els.progressMilestones.innerHTML = PROGRESS_MILESTONES.map((m) =>
      `<div class="progress-milestone${s.total >= m ? " reached" : ""}"><strong>${m}</strong><span>${m === 1 ? "Training" : "Trainings"}</span></div>`).join("");
    els.progressNextText.textContent = s.next
      ? `Noch ${s.next - s.total} ${s.next - s.total === 1 ? "Training" : "Trainings"} bis zum nächsten Meilenstein (${s.next}).`
      : "Alle Meilensteine geschafft. Respekt!";
  }
  function setProgressGoal(delta) {
    const p = loadProgress();
    p.weekGoal = Math.max(1, Math.min(14, p.weekGoal + delta));
    writeJSON(PROGRESS_KEY, p);
    renderProgressScreen();
  }
  els.progressGoalMinus.addEventListener("click", () => setProgressGoal(-1));
  els.progressGoalPlus.addEventListener("click", () => setProgressGoal(1));
  els.todayProgressOpenBtn.addEventListener("click", () => showScreen("progressScreen"));
  els.progressBackBtn.addEventListener("click", () => showScreen("todayHome"));
  const PROGRAM_HISTORY_KINDS = ["program", "breath-program", "workout-plan", "movement-plan", "cardio-plan", "combo"];
  function isCompleted(progKey) {
    return loadHistory().some((e) => PROGRAM_HISTORY_KINDS.includes(e.kind) && e.progKey === progKey);
  }
  function startOfWeek() {
    const d = new Date();
    d.setHours(0, 0, 0, 0);
    d.setDate(d.getDate() - ((d.getDay() + 6) % 7));
    return d;
  }
  const WEEKDAYS = ["So", "Mo", "Di", "Mi", "Do", "Fr", "Sa"];
  function ratingLabel(kind) { return kind === "breath" || kind === "breath-program" ? "Ruhe" : "Fokus"; }
  const HISTORY_VISIBLE_SHORT = 3;
  const HISTORY_VISIBLE_EXPANDED = 200; // effectively "all" - addHistory() itself caps storage at 200
  function renderHistoryInto(sectionEl, statsEl, listEl, moreBtn, list) {
    // Always shown, also before the first training, so every area home has
    // the same frame (Fabian's rule; review 2026-10-05 thought it missing).
    sectionEl.hidden = false;
    const clearBtn = sectionEl.querySelector('[id$="istoryClearBtn"]');
    if (clearBtn) clearBtn.hidden = !list.length;
    if (!list.length) {
      statsEl.innerHTML = "";
      listEl.innerHTML = '<li class="history-empty">Noch kein Training gespeichert. Nach deinem ersten Training siehst du es hier.</li>';
      if (moreBtn) moreBtn.hidden = true;
      return;
    }
    const weekStart = startOfWeek();
    const week = list.filter((e) => new Date(e.ts) >= weekStart);
    const weekSec = week.reduce((s, e) => s + (e.seconds || 0), 0);
    statsEl.innerHTML =
      `<div class="stat"><strong>${week.length}</strong><span>Trainings diese Woche</span></div>` +
      `<div class="stat"><strong>${week.length ? fmtMinutes(weekSec) : "–"}</strong><span>Trainingszeit diese Woche</span></div>` +
      `<div class="stat"><strong>${list.length}</strong><span>Trainings gesamt</span></div>`;
    const expanded = listEl.dataset.expanded === "1";
    const visibleCount = expanded ? HISTORY_VISIBLE_EXPANDED : HISTORY_VISIBLE_SHORT;
    listEl.innerHTML = list.slice(0, visibleCount).map((e) => {
      const d = new Date(e.ts);
      const date = `${WEEKDAYS[d.getDay()]}, ${String(d.getDate()).padStart(2, "0")}.${String(d.getMonth() + 1).padStart(2, "0")}.`;
      const rating = e.rating ? ` · ${ratingLabel(e.kind)} ${e.rating}/5` : "";
      const note = e.note ? ` · ${esc(e.note)}` : "";
      return `<li><span class="h-date">${date}</span><span class="h-title">${esc(e.title)}</span><span class="h-meta">${fmtMinutes(e.seconds || 0)}${note}${rating}</span></li>`;
    }).join("");
    moreBtn.hidden = list.length <= HISTORY_VISIBLE_SHORT;
    moreBtn.textContent = expanded ? "Weniger anzeigen" : "Alle anzeigen";
  }
  // One "Gesamter Trainingsverlauf" section per area home (Fabian, 2026-10-04:
  // it was missing in Cardio, NAT and Test). A new area adds its prefix here
  // and the same markup block (ids <prefix>HistorySection/Stats/List/MoreBtn/ClearBtn).
  const HISTORY_PREFIXES = ["", "breath", "movement", "workout", "cardio", "nat", "test", "free", "activation"];
  const historyEl = (prefix, part) => document.getElementById(prefix ? prefix + "History" + part : "history" + part);
  function renderHistory() {
    const list = loadHistory();
    HISTORY_PREFIXES.forEach((pre) => {
      const sec = historyEl(pre, "Section");
      if (sec) renderHistoryInto(sec, historyEl(pre, "Stats"), historyEl(pre, "List"), historyEl(pre, "MoreBtn"), list);
    });
  }
  function clearHistory() {
    confirmDialog("Deinen Trainingsverlauf auf diesem Gerät löschen?", () => {
      writeJSON(HISTORY_KEY, []);
      renderHistory();
    });
  }
  HISTORY_PREFIXES.forEach((pre) => {
    const listEl = historyEl(pre, "List");
    if (!listEl) return;
    historyEl(pre, "ClearBtn").addEventListener("click", clearHistory);
    historyEl(pre, "MoreBtn").addEventListener("click", () => { listEl.dataset.expanded = listEl.dataset.expanded === "1" ? "0" : "1"; renderHistory(); });
  });

  // Rating widget shown on the finish screens.
  function renderRating(container, entryId, question) {
    container.innerHTML =
      `<div class="rating-q">${esc(question || "Wie fokussiert warst du?")}</div>` +
      `<div class="rating-row">${[1, 2, 3, 4, 5].map((n) => `<button data-rate="${n}" aria-label="${n} von 5">${n}</button>`).join("")}</div>` +
      `<div class="rating-scale"><span>kaum</span><span>voll da</span></div>` +
      `<div class="rating-thanks" hidden>Danke – gespeichert.</div>`;
    container.querySelectorAll("[data-rate]").forEach((btn) => {
      btn.addEventListener("click", () => {
        const n = Number(btn.dataset.rate);
        rateHistory(entryId, n);
        container.querySelectorAll("[data-rate]").forEach((b) => setActive(b, Number(b.dataset.rate) === n));
        container.querySelector(".rating-thanks").hidden = false;
      });
    });
  }

  // ---- Focus trap for the sheets/modal (tips, video) ----
  // Keeps Tab from leaving the open dialog and returns focus to whatever
  // opened it on close, instead of letting it fall through to elements
  // underneath (e.g. Tab landing on "Verlauf löschen" behind the sheet).
  const FOCUSABLE = 'button, [href], input, select, textarea, [tabindex]:not([tabindex="-1"])';
  function focusFirstIn(sheetEl) {
    const f = sheetEl.querySelector(FOCUSABLE);
    // preventScroll: focusing a control far down a long sheet (e.g. a link
    // in the tips list) used to open the sheet scrolled past its heading.
    if (f) f.focus({ preventScroll: true });
    sheetEl.scrollTop = 0;
    sheetEl.querySelectorAll(".sheet-inner").forEach((el) => { el.scrollTop = 0; });
  }
  function trapTabKey(sheetEl, e) {
    if (e.key !== "Tab" || sheetEl.hidden) return;
    const list = sheetEl.querySelectorAll(FOCUSABLE);
    if (!list.length) return;
    const first = list[0], last = list[list.length - 1];
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last.focus(); }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first.focus(); }
  }

  // ---- Shared top-clearance measurement for every full-stage exercise
  // (Positionen merken/Blitz-Raster/Flash/Trail/Search/Corsi/Reaktionsfeld etc.) -
  // their stage fills the whole player from y=0, with the instruction hint
  // (".remember-hint", short status blips OR - since Trail Making Test's
  // real bug report - a much longer, wrapping instruction sentence) and the
  // player-bar floating on top via z-index. A hardcoded pixel minY can't
  // account for wrapped-hint height (varies with instruction length) or
  // safe-area notch size (varies per device), so every exercise that
  // scatters markers/targets across its whole stage should measure the
  // hint's and bar's real rendered bottom edge instead. Falls back to
  // fallbackMinY only while the stage isn't actually laid out yet
  // (rect.height === 0, e.g. read before the player is unhidden).
  // IMPORTANT: the returned value is meant to be used as a constraint on a
  // marker's CENTRE y - every caller positions markers via translate(-50%,
  // -50%), so the marker's own rendered TOP edge sits `halfSizePx` above its
  // centre. Without adding halfSizePx here, a centre placed exactly at the
  // hint's measured bottom edge would still visually overlap it by
  // (halfSizePx - marginPx); this bit past every caller the first time
  // (caught via a repeated Playwright run, not a single deterministic one -
  // the overlap only happens for markers whose random draw lands near this
  // boundary, so a single-shot test can easily miss it).
  // On a narrow phone the player bar can wrap to two rows and then covered
  // the on-stage hint (fixed CSS top:68px). This moves a hint just below
  // the bar's real bottom edge whenever needed, and back to its CSS
  // position when the bar is one row again.
  function placeHintBelowBar(hintEl, barEl) {
    if (!hintEl || !barEl) return;
    hintEl.style.top = "";
    const barBottom = barEl.getBoundingClientRect().bottom;
    const hintTop = hintEl.getBoundingClientRect().top;
    if (!barBottom || !hintEl.offsetParent || hintTop >= barBottom + 6) return;
    const parentTop = hintEl.offsetParent.getBoundingClientRect().top;
    hintEl.style.top = Math.round(barBottom + 8 - parentTop) + "px";
  }
