      if (cfg.countdownS > 0 && (countEnd || countStart)) cueCountdownBeep(workoutBeepedSeconds, remain, cfg.countdownS);
      if (frame.type === "work") cueTickCheck(workoutBeepedSeconds, elapsed - frame.t0, remain, cfg);
